const raw = $input.first().json.data ?? $input.first().json;
const doc = typeof raw === 'string' ? JSON.parse(raw) : raw;
const faults = doc.faults;
if (!Array.isArray(faults) || !faults.length) throw new Error('No faults parsed');

const EXPECTED = Number($('Doc variant').first().json.expected_count);
if (faults.length !== EXPECTED)
  throw new Error(`Expected ${EXPECTED} faults, got ${faults.length} — re-probe before ingesting`);

// The file states its own count; if the two disagree the transcription is torn.
const declared = Number(doc.source?.fault_count);
if (Number.isFinite(declared) && declared !== faults.length)
  throw new Error(`source.fault_count says ${declared} but the list has ${faults.length}`);

// ⛔ THE GUARD THAT MATTERS. The BJCP source is two columns — Characteristic and
// Possible Solutions — so there is no cause data anywhere in it. If a future
// regeneration of this file adds a `cause`, it was INFERRED, and inferring causes
// is precisely the fabricated-content failure the closed-book design prevents.
// Refuse the run rather than let invented causation into the corpus.
const ALLOWED = new Set(['name', 'descriptors', 'solutions']);
const rows = faults.map((f, i) => {
  for (const k of Object.keys(f))
    if (!ALLOWED.has(k))
      throw new Error(`Fault ${i} ("${f.name ?? '?'}") has unexpected field "${k}". `
        + `If this is a cause, it was inferred — the source has none. Refusing.`);

  const name = String(f.name ?? '').trim();
  const solutions = String(f.solutions ?? '').trim();
  if (!name) throw new Error(`Fault ${i} has no name`);
  if (!solutions) throw new Error(`Fault "${name}" has no solutions`);
  const descriptors = Array.isArray(f.descriptors)
    ? f.descriptors.map(d => String(d).trim()).filter(Boolean) : [];
  if (!descriptors.length) throw new Error(`Fault "${name}" has no descriptors`);
  return { name, descriptors, solutions };
});

const dup = rows.map(r => r.name).filter((v, i, a) => a.indexOf(v) !== i);
if (dup.length) throw new Error(`Duplicate fault name(s): ${dup.join(', ')}`);

return [{ json: { rows, stats: {
  faults: rows.length,
  descriptors: rows.reduce((n, r) => n + r.descriptors.length, 0),
  solution_words: rows.reduce((n, r) => n + r.solutions.split(/\s+/).length, 0),
} } }];

const items = $input.all();
return [{ json: {
  ids:    items.map(i => i.json.id),
  inputs: items.map(i => i.json.content),
}}];

const src = $('Assemble embed input').first().json;
const emb = $json.embeddings;
if (!Array.isArray(emb) || emb.length !== src.ids.length)
  throw new Error(`Embedding count ${emb?.length} != inputs ${src.ids.length}`);
if (emb[0].length !== 1024)
  throw new Error(`Expected 1024 dims, got ${emb[0].length} — schema mismatch`);
return src.ids.map((id, i) => ({
  json: { chunk_id: id, embedding: '[' + emb[i].join(',') + ']' },
}));

const r = $json;
if (r.missing > 0) throw new Error(`${r.missing} of ${r.total} cards have no embedding — not promoted`);
if (!r.is_current) throw new Error(`Version ${r.version_id} did not become current`);
return [{ json: r }];
